const record=$input.first().json?.body??$input.first().json;
const fields=record?.fields??{};
const preferred=['Client Name','Name','Client','Company Name','Workspace Name'];
let clientName='';
for(const name of preferred){const value=fields[name];if(typeof value==='string'&&value.trim()){clientName=value.trim();break;}}
if(!clientName){const value=Object.values(fields).find(item=>typeof item==='string'&&item.trim());clientName=String(value??'').trim();}
if(!clientName)throw new Error('The Workspace IDs record has no readable client name.');
const recordId=$('Validate Refresh Request').first().json.recordId;
const escaped=clientName.replace(/"/g,'\\"');
// Explicit same-client workspace group; ordinary workspace histories remain isolated.
const groups={'reczzwlJfHOwdUNzc':['Twenty West Media','Twenty West Media (Internal)'],'recynyHPighsOPpjd':['Twenty West Media','Twenty West Media (Internal)']};
const names=groups[recordId]||[clientName];
const workspaceIds=['reczzwlJfHOwdUNzc','recynyHPighsOPpjd'].includes(recordId)?['65','66']:[String(fields.ID??'')].filter(Boolean);
const clientRecordIds=['reczzwlJfHOwdUNzc','recynyHPighsOPpjd'].includes(recordId)?['reczzwlJfHOwdUNzc','recynyHPighsOPpjd']:[recordId];
const clientFormula='OR('+[...names.map(name=>'{Clients Table}='+JSON.stringify(name)),...workspaceIds.map(id=>'{Workspace ID (Bison)}='+JSON.stringify(id))].join(',')+')';
const eligibleFormula='OR({Date of Call Booked}!=BLANK(),{Opportunity Status}="WON",{Pipeline Stage}="Booked Meeting",{Pipeline Stage}="Completed Meeting",{Pipeline Stage}="Closed Deal",{Client Closed Deals}!=BLANK(),AND(OR({Lead Status}="Interested",{Lead Status}="Meeting Request"),{Status timestamp}!=BLANK(),DATETIME_DIFF(NOW(),{Status timestamp},"seconds")<=2592000))';
const formula='AND('+clientFormula+','+eligibleFormula+')';
const wantedFields=['domain exclusion','Date of Call Booked','Last Lead Interaction','Lead Created','Lead Status','Pipeline Stage','Opportunity Status','Status timestamp','Client Closed Deals','Clients Table','Workspace ID (Bison)'];
const fieldsQuery=wantedFields.map(name=>'&fields%5B%5D='+encodeURIComponent(name)).join('');
const url='https://api.airtable.com/v0/appxqINt5XKw7a76A/Emails?pageSize=100'+fieldsQuery+'&filterByFormula='+encodeURIComponent(formula);
const onboardingIds=Array.isArray(fields['Onboarding'])?fields['Onboarding']:[];
const onboardingRecordId=String(onboardingIds[0]??'').trim();
const onboardingField='Do you have a list of contacts who we SHOULD NOT CONTACT? If so, please upload it here (make sure to include company website URLs):';
const onboardingUrl=onboardingRecordId
  ? 'https://api.airtable.com/v0/appxqINt5XKw7a76A/Onboarding/'+encodeURIComponent(onboardingRecordId)
  : 'https://api.airtable.com/v0/appxqINt5XKw7a76A/Onboarding?pageSize=1&filterByFormula='+encodeURIComponent('FIND("'+recordId+'",ARRAYJOIN({Record ID (from Workspace IDs)}))');
return [{json:{recordId,clientName,clientRecordIds,workspaceIds,url,onboardingUrl,onboardingField,suppressionDays:30}}];

const parse = value => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return value; }
};

const emailResponses = $('Get Client Domain Exclusions').all().map(item => parse(item.json?.body ?? item.json));
const records = emailResponses.flatMap(value => Array.isArray(value?.records) ? value.records : (value?.fields ? [value] : []));
if (emailResponses.at(-1)?.offset) throw new Error('Client exclusions were not refreshed because Airtable pagination did not finish.');

const blockedHosts = new Set([
  'docs.google.com',
  'drive.google.com',
  'sheets.google.com',
  'airtable.com',
  'airtableusercontent.com',
  'dropbox.com','gmail.com','googlemail.com','outlook.com','hotmail.com','live.com','yahoo.com','yahoo.co.uk','aol.com','icloud.com','me.com','msn.com','proton.me','protonmail.com',
]);
const hostnamePattern = '(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,63}';
const emailPattern = new RegExp('[a-z0-9._%+-]+@(' + hostnamePattern + ')', 'i');
const hostPattern = new RegExp('(?:https?:\\/\\/)?(?:www\\.)?(' + hostnamePattern + ')(?=[:\\/?#\\s,;\\"\\\'<>()[\\]]|$)', 'i');
const tokenPattern = new RegExp('[a-z0-9._%+-]+@' + hostnamePattern + '|(?:https?:\\/\\/)?(?:www\\.)?' + hostnamePattern + '(?=[:\\/?#\\s,;\\"\\\'<>()[\\]]|$)', 'gi');

const clean = value => {
  const text = String(value ?? '').trim().toLowerCase();
  if (!text) return '';
  const email = text.match(emailPattern);
  if (email) return email[1].replace(/^www\./, '');
  const host = text.match(hostPattern);
  return host ? host[1].replace(/^www\./, '') : '';
};
const valid = domain => {
  if (!domain || domain.length > 253 || blockedHosts.has(domain)) return false;
  const labels = domain.split('.');
  return labels.length > 1
    && /^[a-z]{2,63}$/.test(labels.at(-1))
    && labels.every(label => label.length > 0 && label.length <= 63 && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label));
};
const addTokens = (target, value) => {
  if (value === undefined || value === null) return;
  const text = typeof value === 'object' ? String(value.name ?? value.url ?? value.value ?? '') : String(value);
  const tokens = text.match(tokenPattern) ?? [];
  for (const token of tokens) {
    const domain = clean(token);
    if (valid(domain)) target.add(domain);
  }
};
const dateValue = value => {
  if (!value) return 0;
  const timestamp = Date.parse(Array.isArray(value) ? value[0] : value);
  return Number.isFinite(timestamp) ? timestamp : 0;
};

const cutoff = new Date();
cutoff.setTime(cutoff.getTime() - 30 * 86400000);
const cutoffMs = cutoff.getTime();
const rolling = new Set();
const booked = new Set();
const explicitDnc = new Set();
let expiredCount = 0;

for (const record of records) {
  const fields = record?.fields ?? {};
  const scope=$('Build Client Email Query').first().json;
  const links=fields['Clients Table']??[];
  if(!links.some(id=>(scope.clientRecordIds??[]).includes(id)) && !(scope.workspaceIds??[]).includes(String(fields['Workspace ID (Bison)']??'')))continue;
  const raw = fields['domain exclusion'];
  const domains = new Set();
  for (const value of (Array.isArray(raw) ? raw : [raw])) addTokens(domains, value);
  if (!domains.size) continue;
  const hasBookedMeeting = Boolean(fields['Date of Call Booked']) || ['Booked Meeting','Completed Meeting','Closed Deal'].includes(fields['Pipeline Stage']) || fields['Opportunity Status']==='WON' || (Array.isArray(fields['Client Closed Deals']) && fields['Client Closed Deals'].length>0);
  const isInterested = ['Interested','Meeting Request'].includes(fields['Lead Status']);
  const activityMs = dateValue(fields['Status timestamp']);
  if (hasBookedMeeting) {
    for (const domain of domains) booked.add(domain);
    continue;
  }
  if (isInterested && activityMs >= cutoffMs) {
    for (const domain of domains) rolling.add(domain);
  } else {
    expiredCount += domains.size;
  }
}

const onboardingResponse = parse($('Get Client Onboarding').first().json?.body ?? $('Get Client Onboarding').first().json);
const onboardingRecord = Array.isArray(onboardingResponse?.records) ? onboardingResponse.records[0] : onboardingResponse;
const onboardingText = String(onboardingRecord?.fields?.[$('Build Client Email Query').first().json.onboardingField] ?? '');
const onboarding = new Set();
addTokens(onboarding, onboardingText);

const sheetResponse = $input.first().json;
const sheetText = String(sheetResponse?.body ?? sheetResponse?.data ?? '');
const sheetDomains = new Set();
addTokens(sheetDomains, sheetText);

const workspace=$('Get Client Workspace').first().json;
const workspaceFields=(workspace.body??workspace).fields??{};
addTokens(booked,workspaceFields['Booked Meeting Exclusion Domains']);
const overrides=new Set();addTokens(overrides,workspaceFields['Booked Meeting Exclusion Overrides']);
for(const domain of overrides)booked.delete(domain);
const domains = [...new Set([...rolling, ...booked, ...explicitDnc, ...onboarding, ...sheetDomains])].sort();
const client = $('Build Client Email Query').first().json;
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
return [{
  json: {
    recordId: client.recordId,
    clientName: client.clientName,
    query_name: client.clientName + ' Lead List Suppression ' + stamp,
    domains,
    tags: ['lead-list-center', 'client-suppression', 'interested-30-days', 'onboarding-permanent'],
    count: domains.length,
    hasDomains: domains.length > 0,
    recordsScanned: records.length,
    pagesScanned: emailResponses.length,
    suppressionDays: 30,
    rollingDomainCount: rolling.size,
    bookedPermanentCount: booked.size,
    bookedDomainLedger: [...booked].sort().join('\n'),
    dncPermanentCount: explicitDnc.size,
    onboardingPermanentCount: onboarding.size,
    sheetDomainCount: sheetDomains.size,
    expiredDomainCount: expiredCount,
  },
}];
